-- SafeRoute Supabase PostgreSQL schema
-- Run this in Supabase Dashboard -> SQL Editor -> New query.
-- UUIDs and timestamps are generated by the Spring Boot application.
create table if not exists public.users (
    id uuid primary key,
    name varchar(80) not null,
    email varchar(254) not null unique,
    password_hash varchar(100) not null,
    role varchar(20) not null default 'USER',
    created_at timestamptz not null default now()
);

create index if not exists idx_users_email on public.users(email);

create table if not exists public.reports (
    id uuid primary key,
    title varchar(120) not null,
    description varchar(2000) not null,
    category varchar(40) not null,
    severity varchar(20) not null,
    latitude double precision not null check (latitude between -90 and 90),
    longitude double precision not null check (longitude between -180 and 180),
    address varchar(200),
    reported_by varchar(36) not null,
    status varchar(20) not null default 'PENDING',
    verification_count integer not null default 0,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

create index if not exists idx_reports_created_at on public.reports(created_at desc);
create index if not exists idx_reports_status_created on public.reports(status, created_at desc);
create index if not exists idx_reports_coordinates on public.reports(latitude, longitude);

-- The Spring Boot API authenticates users with JWT and accesses PostgreSQL using
-- the server-only Supabase database credential. Do not put that credential in VITE_*
-- variables or expose it in the browser. Keep Supabase RLS enabled if using the
-- Supabase Data API directly; the app backend does not use that Data API.
